#include <map>

bool isAncestor(const std::map<int, int>& parentOf, int ancestor, int node)
{
    auto it{ parentOf.find(node) };
    int steps{ 0 };
    while (it != parentOf.end() && it->second != -1 && steps++ < static_cast<int>(parentOf.size()))
    {
        if (it->second == ancestor) return true;
        it = parentOf.find(it->second);
    }
    return false;
}

bool reparent(std::map<int, int>& parentOf, int node, int newParent)
{
    if (!parentOf.count(node)) return false;
    if (newParent != -1)
    {
        if (!parentOf.count(newParent)) return false;
        if (newParent == node || isAncestor(parentOf, node, newParent)) return false;
    }
    parentOf[node] = newParent;
    return true;
}

unitTests:
std::map<int, int> scene() { return { { 1, -1 }, { 2, 1 }, { 3, 2 }, { 4, 1 }, { 5, -1 } }; }
TEST("ancestors") { auto s = scene(); CHECK(isAncestor(s, 1, 3)); CHECK(isAncestor(s, 2, 3)); CHECK(!isAncestor(s, 4, 3)); CHECK(!isAncestor(s, 3, 3)); CHECK(!isAncestor(s, 3, 1)); }
TEST("a normal move") { auto s = scene(); CHECK(reparent(s, 3, 4)); CHECK_EQ(s[3], 4); }
TEST("to the root") { auto s = scene(); CHECK(reparent(s, 2, -1)); CHECK_EQ(s[2], -1); }
TEST("onto itself") { auto s = scene(); CHECK(!reparent(s, 2, 2)); CHECK_EQ(s[2], 1); }
TEST("onto a descendant") { auto s = scene(); CHECK(!reparent(s, 1, 3)); CHECK_EQ(s[1], -1); }
TEST("unknown objects") { auto s = scene(); CHECK(!reparent(s, 9, 1)); CHECK(!reparent(s, 1, 9)); }

